result:
.main-pic img{
  width: 100%;
  height: 375px;
}
.menu_box{
  width: 77px;
  height: 29px;
  border-radius: 14px;
  border: 1px solid rgba(0, 0, 0, 0.1);
}
.menu_box img{
  width: 16px;
  height: 16px;
}
.menu_box .menu_line {
  width: 1px;
  height: 15px;
  background: #B3B3B3;
  margin: 0 10px;
}
.share-icon{
  margin-right: 10px;
  img{
    width: 16px;
    height: 16px;
  }
}
.dot-line{
  width: 100%;
  position: absolute;
  left: 0;
  bottom: 27px;
  .item{
    width: 66px;
    height: 2px;
    border-radius: 2px;
    background: #fff;
    & ~ .item{
      margin-left: 4px;
    }
  }
}
.info-box{
  background: linear-gradient(180deg, #ffffff 0%, #ffffff 54%, rgba(255, 255, 255, 0) 100%);
  margin-top: -17px;
  border-radius: 20px 20px 0 0;
}
.svip{
  width: 63px;
  height: 14px;
  border-radius: 8px;
  background: #FFF0D1;
  font-size: 9px;
  color: #333;
  margin-left: 10px;
  .left{
    width: 28px;
    height: 14px;
    line-height: 14px;
    padding-left: 4px;
    border-radius: 8px 0 8px 8px;
    color: #FDDAA4;
    background: #333;
  }
}

.pic-list{
  width: 100%;
  padding-top: 18px;
  .pic{
    width: 40px;
    height: 40px;
    border-radius: 8px;
  }
}
.tag{
  display: inline-flex;
  justify-content: center;
  align-items: center;
  height: 22px;
  padding: 0 8px;
  font-size: 11px;
  color: #e93323;
  background: rgba(233, 51, 35, 0.1);
  margin-right: 8px;
  border-radius: 4px;
}
.pro-title{
  font-size: 15px;
  font-weight: 500;
  line-height: 21px;
  margin-top: 10px;
}
.fs-11{
  font-size: 11px;
}
.mt-13{
  margin-top: 13px;
}
.red{
  color: #e93323;
}
.lh-15{
  line-height: 15px;
}
